-- Run after the product/order schema and embedding_schema.sql are installed.
-- Demo embeddings use simple 1536-dimensional vectors; replace them with
-- embeddings generated by the model used by the application for real searches.
BEGIN;

INSERT INTO product_model (model_code, name)
VALUES ('ROBO-DEMO-01', 'Demo Robot Vacuum')
ON CONFLICT (model_code) DO UPDATE SET name = EXCLUDED.name;

INSERT INTO product (serial_number, model_id, manufactured_on)
VALUES
    ('RB-DEMO-0001', (SELECT id FROM product_model WHERE model_code = 'ROBO-DEMO-01'), DATE '2026-01-15'),
    ('RB-DEMO-0002', (SELECT id FROM product_model WHERE model_code = 'ROBO-DEMO-01'), DATE '2026-02-10')
ON CONFLICT (serial_number) DO UPDATE
SET model_id = EXCLUDED.model_id,
    manufactured_on = EXCLUDED.manufactured_on;

INSERT INTO part (part_number, name, category)
VALUES
    ('PCB-DEMO-001', 'Main control board', 'PCB'),
    ('MOTOR-DEMO-001', 'Brushless drive motor', 'MOTOR'),
    ('PART-DEMO-001', 'Dust bin sensor', 'OTHER')
ON CONFLICT (part_number) DO UPDATE
SET name = EXCLUDED.name,
    category = EXCLUDED.category;

INSERT INTO model_part (model_id, part_id)
SELECT m.id, p.id
FROM product_model m
CROSS JOIN part p
WHERE m.model_code = 'ROBO-DEMO-01'
  AND p.part_number IN ('PCB-DEMO-001', 'MOTOR-DEMO-001', 'PART-DEMO-001')
ON CONFLICT DO NOTHING;

INSERT INTO app_user (email, name, role, active)
VALUES
    ('demo.technician@example.test', 'Demo Technician', 'TECHNICIAN', true),
    ('demo.quality@example.test', 'Demo Quality Manager', 'QUALITY_MANAGER', true)
ON CONFLICT (email) DO UPDATE
SET name = EXCLUDED.name,
    role = EXCLUDED.role,
    active = EXCLUDED.active;

INSERT INTO warehouse (name, region, address, phone)
SELECT 'Demo Seoul Warehouse', 'Seoul', '100 Demo-ro, Seoul', '+82-2-555-0101'
WHERE NOT EXISTS (
    SELECT 1 FROM warehouse WHERE name = 'Demo Seoul Warehouse'
);
UPDATE warehouse SET location = 'B동 3열 2단'
WHERE name = 'Demo Seoul Warehouse';

INSERT INTO factory (name, country, region, address, phone)
SELECT 'Demo Busan Parts Factory', 'KR', 'Busan', '200 Factory-ro, Busan', '+82-51-555-0102'
WHERE NOT EXISTS (
    SELECT 1 FROM factory WHERE name = 'Demo Busan Parts Factory'
);
UPDATE factory
SET contact_name = 'Demo Contact', email = 'parts.busan@example.test'
WHERE name = 'Demo Busan Parts Factory';

INSERT INTO inventory (warehouse_id, part_id, on_hand, reserved)
SELECT w.id, p.id, 25, 3
FROM warehouse w
CROSS JOIN part p
WHERE w.name = 'Demo Seoul Warehouse'
  AND p.part_number IN ('PCB-DEMO-001', 'MOTOR-DEMO-001', 'PART-DEMO-001')
ON CONFLICT (warehouse_id, part_id) DO UPDATE
SET on_hand = EXCLUDED.on_hand,
    reserved = EXCLUDED.reserved,
    version = inventory.version + 1;

INSERT INTO part_supplier (part_id, factory_id, lead_days, unit_price)
SELECT p.id, f.id, 5,
       CASE p.part_number
           WHEN 'PCB-DEMO-001' THEN 48000
           WHEN 'MOTOR-DEMO-001' THEN 68000
           ELSE 9500
       END
FROM part p
CROSS JOIN factory f
WHERE p.part_number IN ('PCB-DEMO-001', 'MOTOR-DEMO-001', 'PART-DEMO-001')
  AND f.name = 'Demo Busan Parts Factory'
ON CONFLICT (part_id, factory_id) DO UPDATE
SET lead_days = EXCLUDED.lead_days,
    unit_price = EXCLUDED.unit_price;

INSERT INTO purchase_order (
    case_reference, request_key, requested_by, status
)
VALUES (
    'DEMO-CASE-0001',
    '00000000-0000-4000-8000-000000000001',
    (SELECT id FROM app_user WHERE email = 'demo.technician@example.test'),
    'PENDING'
)
ON CONFLICT (request_key) DO UPDATE
SET case_reference = EXCLUDED.case_reference,
    requested_by = EXCLUDED.requested_by
WHERE purchase_order.status = 'PENDING';

-- Replace only this demo order's lines, so rerunning the seed is safe.
DELETE FROM purchase_order_item
WHERE order_id = (
    SELECT id FROM purchase_order
    WHERE request_key = '00000000-0000-4000-8000-000000000001'
      AND status = 'PENDING'
);

INSERT INTO purchase_order_item (
    order_id, part_id, quantity, warehouse_id, factory_id
)
SELECT po.id, p.id, 2, w.id, NULL
FROM purchase_order po
CROSS JOIN part p
CROSS JOIN warehouse w
WHERE po.request_key = '00000000-0000-4000-8000-000000000001'
  AND po.status = 'PENDING'
  AND p.part_number = 'PCB-DEMO-001'
  AND w.name = 'Demo Seoul Warehouse';

INSERT INTO purchase_order_item (
    order_id, part_id, quantity, warehouse_id, factory_id
)
SELECT po.id, p.id, 1, NULL, f.id
FROM purchase_order po
CROSS JOIN part p
CROSS JOIN factory f
WHERE po.request_key = '00000000-0000-4000-8000-000000000001'
  AND po.status = 'PENDING'
  AND p.part_number = 'MOTOR-DEMO-001'
  AND f.name = 'Demo Busan Parts Factory';

-- Use a simple distinct vector direction per demo record. These are structural
-- placeholders, not meaningful model-generated embeddings.
DELETE FROM product_embedding
WHERE content IN (
    'Demo embedding: ROBO-DEMO-01 robot vacuum model',
    'Demo embedding: PCB-DEMO-001 main control board'
);

INSERT INTO product_embedding (model_id, content, embedding)
SELECT id,
       'Demo embedding: ROBO-DEMO-01 robot vacuum model',
       ('[1' || repeat(',0', 1535) || ']')::vector
FROM product_model
WHERE model_code = 'ROBO-DEMO-01';

INSERT INTO product_embedding (part_id, content, embedding)
SELECT id,
       'Demo embedding: PCB-DEMO-001 main control board',
       ('[0,1' || repeat(',0', 1534) || ']')::vector
FROM part
WHERE part_number = 'PCB-DEMO-001';

INSERT INTO purchase_order_embedding (
    purchase_order_id, content, embedding
)
SELECT po.id,
       'Demo order: robot vacuum PCB and motor replacement parts',
       ('[0,0,1' || repeat(',0', 1533) || ']')::vector
FROM purchase_order po
WHERE po.request_key = '00000000-0000-4000-8000-000000000001'
ON CONFLICT (purchase_order_id) DO UPDATE
SET content = EXCLUDED.content,
    embedding = EXCLUDED.embedding,
    updated_at = now();

COMMIT;
